pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Ensure the external call does not revert by routing to a helper that succeeds
        EmptySucceed helper = new EmptySucceed();
        address helperAddr = address(helper);
        bool ok;
        try c.transfer(from, helperAddr, _tos, v) returns (bool ret) {
            ok = true;
            assertTrue(ret);
        } catch {
            ok = false;
        }
        if (ok) {
            // If it didn't revert, the return value must be true
        }
    }
}

contract EmptySucceed {
    fallback() external payable { }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, uint v) public {
        address[] memory tos = new address[](0);
        bool ok = true;
        try c.transfer(from, caddress, tos, v) { } catch { ok = false; }
        assertTrue(!ok, "empty _tos did not revert");
    }
}
